def effective_limit(value, default=10):
    if value is None:
        return default
    elif value == 0:
        return 0
    elif isinstance(value, int) and value > 0:
        return value
    elif isinstance(value, int) and value < 0:
        raise ValueError("Negative limit not allowed")
    else:
        # Should handle other types if necessary, but based on requirements, we assume int or None
        return value

import unittest
import settings

class TestEffectiveLimit(unittest.TestCase):
    def test_none_is_default(self):
        # None means default (default is 10 in the implementation if not provided)
        self.assertEqual(settings.effective_limit(None), 10)

    def test_zero_is_disabled(self):
        # Zero means disabled and must stay zero
        self.assertEqual(settings.effective_limit(0), 0)

    def test_positive_int_overrides(self):
        # Positive int overrides default
        self.assertEqual(settings.effective_limit(5), 5)

    def test_negative_int_raises_value_error(self):
        # Negative int raises ValueError
        with self.assertRaises(ValueError):
            settings.effective_limit(-5)

    def test_default_value_if_no_arg_or_implicit(self):
        # Testing how it behaves if called without explicit arguments, relying on default=10
        # Note: We can't easily test no args without changing the signature/calling convention if we strictly adhere to the original function call patterns
        # We test what happens if we pass None which maps to default.
        self.assertEqual(settings.effective_limit(None, default=5), 5) # Check custom default behavior

if __name__ == '__main__':
    unittest.main()
